#!/usr/bin/env python3
"""
time_adjuster.py

Reads an attendance CSV file, subtracts 4 hours from every value in the
' Clock-out' column, and saves the result as an Excel file at
/workspace/adjusted-april-attendance.xlsx.

Usage:
    python time_adjuster.py <input_csv_path>
"""

import sys
from datetime import datetime, timedelta

import pandas as pd


OUTPUT_PATH = "/workspace/adjusted-april-attendance.xlsx"
CLOCK_OUT_COL = " Clock-out"


def subtract_four_hours(value):
    """Subtract 4 hours from a time-like value.

    Handles datetime/Timestamp objects, datetime.time objects, and strings
    in common time formats (HH:MM, HH:MM:SS) or full datetime strings.
    Returns the value unchanged if it is null/empty or unparseable.
    """
    # Handle missing values
    if value is None:
        return value
    if isinstance(value, float) and pd.isna(value):
        return value

    # pandas Timestamp / datetime
    if isinstance(value, (pd.Timestamp, datetime)):
        return value - timedelta(hours=4)

    # datetime.time -> combine with a dummy date to do arithmetic, then return time
    import datetime as _dt
    if isinstance(value, _dt.time):
        dummy = datetime(2000, 1, 1, value.hour, value.minute, value.second, value.microsecond)
        adjusted = dummy - timedelta(hours=4)
        return adjusted.time()

    # String values
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return value

        # Try several common formats
        formats = ("%H:%M:%S", "%H:%M", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
                   "%m/%d/%Y %H:%M:%S", "%m/%d/%Y %H:%M")
        for fmt in formats:
            try:
                parsed = datetime.strptime(s, fmt)
                adjusted = parsed - timedelta(hours=4)
                # Return in the same format it came in
                return adjusted.strftime(fmt)
            except ValueError:
                continue

        # Fallback: let pandas try to parse it
        try:
            parsed = pd.to_datetime(s)
            adjusted = parsed - timedelta(hours=4)
            # If original looked like a pure time, return as time string
            if len(s) <= 8 and ":" in s:
                return adjusted.strftime("%H:%M:%S")
            return adjusted.strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            return value

    return value


def main():
    if len(sys.argv) < 2:
        print("Usage: python time_adjuster.py <input_csv_path>", file=sys.stderr)
        sys.exit(1)

    input_path = sys.argv[1]

    df = pd.read_csv(input_path)

    if CLOCK_OUT_COL not in df.columns:
        # Try to find a close match (in case the leading space is missing)
        candidates = [c for c in df.columns if c.strip().lower() == "clock-out"]
        if candidates:
            col = candidates[0]
        else:
            print(
                f"Column '{CLOCK_OUT_COL}' not found. Available columns: {list(df.columns)}",
                file=sys.stderr,
            )
            sys.exit(2)
    else:
        col = CLOCK_OUT_COL

    df[col] = df[col].apply(subtract_four_hours)

    df.to_excel(OUTPUT_PATH, index=False)
    print(f"Wrote {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
